import { cn, normalizeProgress, normalizeTone } from '@cascivo/core/pure'
import type { ProgressInput, ToneInput } from '@cascivo/core'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './timeline.module.css'

/** Canonical progress → the value Timeline's stylesheet keys on. */
const STATUS_CLASS: Record<string, string> = {
  pending: 'upcoming',
  active: 'current',
  complete: 'complete',
  error: 'error',
}

/** Canonical tone → the value Timeline's stylesheet keys on. */
const TONE_CLASS: Record<string, string> = {
  neutral: 'neutral',
  info: 'info',
  success: 'success',
  warning: 'warning',
  danger: 'danger',
}

export interface TimelineItem {
  id: string
  title: ReactNode
  description?: ReactNode
  time?: string
  icon?: ReactNode
  /**
   * Where this entry sits in the sequence. Accepts the catalog-wide `Progress` vocabulary
   * (`pending | active | complete | error`) as well as Timeline's own `current` / `upcoming`
   * — they are aliases of `active` / `pending`, so one status enum drives both `Timeline`
   * and `Steps` with no translation.
   */
  status?: ProgressInput
  /**
   * What *kind* of entry this is, as a marker colour — independent of `status`, and
   * overriding it on the marker when set.
   *
   * `status` answers "where is this in the sequence", which is the right question for a
   * tracker (order placed → shipped → delivered). In an activity feed every entry is
   * equally done, and what separates them is what produced them: an automated alert, a
   * human note, a system event. Colouring those by progress renders them identically, so
   * the fastest signal on the page is thrown away. Takes the catalog-wide `Tone`
   * vocabulary (`neutral | info | success | warning | danger`, plus the `error` /
   * `destructive` / `default` aliases).
   *
   * Tone is not a substitute for text: it is not perceivable without colour vision, so
   * keep whatever the tone means also present in `title` or `description`.
   */
  tone?: ToneInput
}

export interface TimelineProps extends HTMLAttributes<HTMLOListElement> {
  items: TimelineItem[]
  /**
   * Axis the entries flow along: `vertical` stacks them down the page (the usual reading
   * order), `horizontal` runs them across.
   *
   * @defaultValue `vertical`
   * @see the component manifest
   */
  orientation?: 'vertical' | 'horizontal'
}

export function Timeline({ items, orientation = 'vertical', className, ...props }: TimelineProps) {
  return (
    <ol
      data-orientation={orientation}
      className={cn(styles['list'], className as string | undefined)}
      {...props}
    >
      {items.map((item) => {
        const progress = normalizeProgress(item.status ?? 'pending')
        return (
          <li
            key={item.id}
            data-status={STATUS_CLASS[progress] ?? 'upcoming'}
            data-tone={item.tone ? (TONE_CLASS[normalizeTone(item.tone)] ?? item.tone) : undefined}
            aria-current={progress === 'active' ? 'step' : undefined}
            className={styles['item']}
          >
            <span className={styles['marker']} aria-hidden="true">
              {/* A failed entry needs an affordance that survives without colour vision, so
                the error marker carries a glyph when the caller gave no icon — matching
                Steps' `✕`, which the shared Progress vocabulary already trained readers on. */}
              {item.icon ?? (progress === 'error' ? '✕' : null)}
            </span>
            <div className={styles['content']}>
              <div className={styles['title']}>{item.title}</div>
              {item.time ? <time className={styles['time']}>{item.time}</time> : null}
              {item.description ? (
                <div className={styles['description']}>{item.description}</div>
              ) : null}
            </div>
          </li>
        )
      })}
    </ol>
  )
}

@layer cascivo.component {
  .list {
    --_marker-size: 0.875rem;
    --_track: var(--cascivo-color-border);
    margin: 0;
    padding: 0;
    list-style: none;
    font-family: var(--cascivo-font-sans);
    color: var(--cascivo-color-text);
    display: flex;
  }

  .list[data-orientation='vertical'] {
    flex-direction: column;
  }

  .list[data-orientation='horizontal'] {
    flex-direction: row;
  }

  .item {
    position: relative;
    display: flex;
    gap: var(--cascivo-space-3);
  }

  .list[data-orientation='vertical'] .item {
    flex-direction: row;
    padding-block-end: var(--cascivo-space-5);
  }

  .list[data-orientation='horizontal'] .item {
    flex-direction: column;
    flex: 1;
    padding-inline-end: var(--cascivo-space-5);
  }

  /* Connector line between markers */
  .list[data-orientation='vertical'] .item::before {
    content: '';
    position: absolute;
    inset-block-start: var(--_marker-size);
    inset-inline-start: calc(var(--_marker-size) / 2);
    inline-size: 1px;
    block-size: calc(100% - var(--_marker-size));
    background-color: var(--_track);
  }

  .list[data-orientation='horizontal'] .item::before {
    content: '';
    position: absolute;
    inset-inline-start: var(--_marker-size);
    inset-block-start: calc(var(--_marker-size) / 2);
    block-size: 1px;
    inline-size: calc(100% - var(--_marker-size));
    background-color: var(--_track);
  }

  .item:last-child::before {
    display: none;
  }

  .marker {
    flex: none;
    inline-size: var(--_marker-size);
    block-size: var(--_marker-size);
    border-radius: var(--cascivo-radius-full);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: var(--cascivo-text-xs);
    line-height: 1;
    border: 2px solid var(--cascivo-color-border);
    background-color: var(--cascivo-color-surface);
    box-sizing: border-box;
  }

  .item[data-status='complete'] .marker {
    border-color: var(--cascivo-color-success);
    background-color: var(--cascivo-color-success);
    color: var(--cascivo-color-success-foreground);
  }

  .item[data-status='current'] .marker {
    border-color: var(--cascivo-color-primary);
    background-color: var(--cascivo-color-primary);
    color: var(--cascivo-color-primary-fg);
  }

  .item[data-status='upcoming'] .marker {
    border-color: var(--cascivo-color-border-strong);
    background-color: var(--cascivo-color-surface);
    color: var(--cascivo-color-text-subtle);
  }

  /* A failed entry must not read as an in-progress one. `error` used to collapse onto
     `current`, so a failed deploy and a running deploy were pixel-identical. */
  .item[data-status='error'] .marker {
    border-color: var(--cascivo-color-destructive);
    background-color: var(--cascivo-color-destructive);
    color: var(--cascivo-color-text-on-destructive);
  }

  /* Tone wins over status on the marker. Same specificity as the status rules above,
     so source order decides — deliberate: an entry that declares what kind of thing it
     is has said something more specific than where it sits in a sequence. */
  .item[data-tone='neutral'] .marker {
    border-color: var(--cascivo-color-border-strong);
    background-color: var(--cascivo-color-border-strong);
    color: var(--cascivo-color-text-on-accent);
  }

  .item[data-tone='info'] .marker {
    border-color: var(--cascivo-color-info);
    background-color: var(--cascivo-color-info);
    color: var(--cascivo-color-info-foreground);
  }

  .item[data-tone='success'] .marker {
    border-color: var(--cascivo-color-success);
    background-color: var(--cascivo-color-success);
    color: var(--cascivo-color-success-foreground);
  }

  .item[data-tone='warning'] .marker {
    border-color: var(--cascivo-color-warning);
    background-color: var(--cascivo-color-warning);
    color: var(--cascivo-color-warning-foreground);
  }

  .item[data-tone='danger'] .marker {
    border-color: var(--cascivo-color-destructive);
    background-color: var(--cascivo-color-destructive);
    color: var(--cascivo-color-destructive-foreground);
  }

  .content {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    padding-block-start: calc((var(--_marker-size) - 1rem) / 2);
  }

  .title {
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-semibold);
    line-height: var(--cascivo-leading-tight);
    color: var(--cascivo-color-text);
  }

  .time {
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-text-subtle);
  }

  .description {
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-normal);
  }
}

@media (forced-colors: active) {
  .marker {
    border: 2px solid CanvasText;
  }

  .item[data-status='current'] .marker {
    border-color: Highlight;
    background-color: Highlight;
  }

  /* Forced colours flatten the palette, so the glyph in the marker is what
     distinguishes a failed entry here. */
  .item[data-status='error'] .marker {
    border-color: CanvasText;
    background-color: Canvas;
    color: CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Timeline',
  description: 'Ordered sequence of events with status markers and a connector line',
  category: 'display',
  clientJs: 'none',
  states: ['complete', 'current', 'upcoming'],
  variants: ['vertical', 'horizontal'],
  sizes: [],
  props: [
    {
      name: 'items',
      description: 'The items to render.',
      type: '{ id: string; title: ReactNode; description?: ReactNode; time?: string; icon?: ReactNode; status?: "complete" | "current" | "upcoming"; tone?: "neutral" | "info" | "success" | "warning" | "danger" }[]',
      required: true,
    },
    {
      name: 'orientation',
      description:
        'Axis the entries flow along: `vertical` stacks them down the page (the usual reading order), `horizontal` runs them across.',
      type: "'vertical' | 'horizontal'",
      required: false,
      default: 'vertical',
    },
  ],
  tokens: [
    '--cascivo-color-border',
    '--cascivo-color-border-strong',
    '--cascivo-color-surface',
    '--cascivo-color-success',
    '--cascivo-color-primary',
    '--cascivo-color-info',
    '--cascivo-color-warning',
    '--cascivo-color-destructive',
    '--cascivo-radius-full',
  ],
  accessibility: { role: 'list', wcag: '2.2-AA', keyboard: [] },
  examples: [
    {
      title: 'Vertical timeline with statuses',
      code: `<Timeline\n  items={[\n    { id: '1', title: 'Order placed', time: '09:00', status: 'complete' },\n    { id: '2', title: 'Shipped', time: '12:30', status: 'current' },\n    { id: '3', title: 'Delivered', status: 'upcoming' },\n  ]}\n/>`,
    },
    {
      title: 'Activity feed coloured by entry type',
      description:
        'In a feed every entry is equally done, so `tone` — not `status` — is what separates them. Keep the meaning in the text too; colour alone is not perceivable.',
      code: `<Timeline\n  items={[\n    { id: '1', title: 'p99 latency 4.2s', description: 'ALERT · monitor', time: '14:28', tone: 'danger' },\n    { id: '2', title: 'Rolling back deploy 4821', description: 'NOTE · bo', time: '14:49', tone: 'neutral' },\n    { id: '3', title: 'Status changed to monitoring', description: 'STATUS · ana', time: '15:12', tone: 'info' },\n    { id: '4', title: 'Merged 2 edits from kim', description: 'MERGE · sync', time: '15:14', tone: 'success' },\n  ]}\n/>`,
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['timeline', 'steps', 'history', 'progress', 'events'],
  intent: {
    whenToUse: [
      'Showing an ordered sequence of events over time (activity feeds, order tracking)',
      'Communicating progress through discrete stages with complete/current/upcoming status',
      'Presenting a chronological history where order is meaningful',
    ],
    whenNotToUse: [
      'Interactive multi-step navigation the user controls — use Tabs or a Stepper',
      'Unordered lists where sequence carries no meaning — use List',
    ],
    antiPatterns: [
      {
        bad: 'Marking several items as status="current" at once',
        good: 'Exactly one current item so aria-current="step" points to a single position',
        why: 'Multiple current markers make the active position ambiguous for assistive tech',
      },
    ],
    related: [
      {
        name: 'List',
        relationship: 'alternative',
        reason: 'List is for unordered prose; Timeline conveys ordered, time-stamped events',
      },
    ],
    a11yRationale:
      'Rendered as an ordered list (ol/li) to convey sequence; the active item carries aria-current="step" and decorative markers are aria-hidden so screen readers read only the text',
    flexibility: [
      {
        area: 'orientation',
        level: 'flexible',
        note: 'vertical for feeds, horizontal for compact progress strips',
      },
      {
        area: 'status semantics',
        level: 'strict',
        note: 'Use a single current item; status drives marker colour via data-status',
      },
      {
        area: 'tone semantics',
        level: 'flexible',
        note: 'tone marks what kind of entry it is and overrides status on the marker; use it for feeds, status for trackers, and keep the meaning in the text as well as the colour',
      },
    ],
  },
}
